// Analyze portfolio composition and risk
const holdings = $json[0].portfolio || [];
const account = $json[1];

const total = account.total || 0;
const cash = account.cash || 0;
const invested = total - cash;

// Calculate allocation
const stocks = holdings.length > 0 ? (invested / total) : 0;
const cashAlloc = cash / total;

// Calculate risk score (0-10)
const riskScore = (stocks * 8 + (holdings.length / 10) * 2).toFixed(1);

// Top holdings
const topHoldings = holdings
  .sort((a, b) => b.value - a.value)
  .slice(0, 5)
  .map(h => `${h.ticker}: £${h.value.toFixed(2)} (${((h.value/invested)*100).toFixed(1)}%)`)
  .join('\n');

const analysis = `
💼 PORTFOLIO ANALYSIS

Total Value: £${total.toFixed(2)}
Invested: £${invested.toFixed(2)}
Cash: £${cash.toFixed(2)}

Allocation:
Stocks: ${(stocks*100).toFixed(1)}%
Cash: ${(cashAlloc*100).toFixed(1)}%

Risk Score: ${riskScore}/10

Top Holdings:
${topHoldings}

Holdings Count: ${holdings.length}
`;

return {
  agent: 'AGENT-PORTFOLIO-MANAGER',
  agent_response: analysis,
  total_value: total,
  invested_value: invested,
  cash: cash,
  risk_score: riskScore,
  holdings_count: holdings.length,
  user_id: '{{ $json.user_id }}'
};

